<?php $title='Portfolio';require '_head.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM portfolio WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: portfolio.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO portfolio(title,description,image,sort_order,active) VALUES(?,?,?,0,1)')->execute([$_POST['title'],$_POST['description'],$_POST['image']]);header('Location: portfolio.php');exit;}$rows=$pdo->query('SELECT * FROM portfolio ORDER BY id DESC')->fetchAll();?><h1>Portfolio</h1><div class="panel"><form method="post"><input name="title" placeholder="Judul" required><textarea name="description" placeholder="Deskripsi"></textarea><input name="image" placeholder="/uploads/portfolio/foto.jpg"><button>Simpan</button></form></div><div class="panel"><?php foreach($rows as $r):?><p><?=e($r['title'])?> — <a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></p><?php endforeach;?></div><?php require '_foot.php';?>